import tiktoken

enc = tiktoken.encoding_for_model("{{model_name}}")

def count(text: str) -> int:
    return len(enc.encode(text))

def count_messages(messages: list[dict]) -> int:
    return sum(count(m["content"]) + 4 for m in messages) + 2

